// BFF Next.js : agrégation côté serveur
export async function getServerSideProps(context) {
  const [product, inventory, content] = await Promise.all([
    commercetools.getProduct(context.params.sku),
    inventoryService.getStock(context.params.sku),
    contentful.getProductContent(context.params.sku)
  ]);
  return { props: { product, inventory, content } };
}

# Exemple simplifié d'éval recall@k
def evaluate_recall(questions, vector_db, k=5):
    hits = 0
    for q in questions:
        results = vector_db.search(q['text'], top_k=k)
        retrieved_ids = [r['chunk_id'] for r in results]
        if q['expected_chunk_id'] in retrieved_ids:
            hits += 1
    return hits / len(questions)

from transformers import pipeline

classifier = pipeline("text-classification", model="./query-complexity-model")

def route_query(query: str) -> str:
    result = classifier(query)[0]
    label = result["label"]
    score = result["score"]

    if label == "SIMPLE" and score > 0.8:
        return "gpt-3.5-turbo"
    elif label == "COMPLEX" and score > 0.75:
        return "gpt-4"
    else:
        return "gpt-4-turbo"  # default safe choice
